import { bookingConflict, notFound } from '../../shared/errors.js';
import {
  normalizeLimit,
  normalizeOffset,
  paginated,
  type Page,
} from '../../shared/pagination.js';
import { parseInstant, parseInterval, requireOrdered, type Interval } from '../../shared/time.js';
import { suggestOpenings } from '../availability/service.js';
import * as rooms from '../rooms/repository.js';
import * as users from '../users/repository.js';
import * as repository from './repository.js';
import { BOOKING_ACTIVE, BOOKING_CANCELLED } from './schema.js';
import type { CreateBookingInput, ListBookingsInput, UpdateBookingInput } from './schema.js';

async function requireRoomAndUser(roomId: string, userId: string): Promise<void> {
  if (!(await rooms.findById(roomId))) {
    throw notFound('Room');
  }
  if (!(await users.findById(userId))) {
    throw notFound('User');
  }
}

/**
 * Rejects an interval that is already taken, pointing the caller at the next
 * openings of the same length so it does not have to guess again.
 */
async function requireFree(roomId: string, interval: Interval, excludeId?: string): Promise<void> {
  const conflict = await repository.findOverlapping(roomId, interval, excludeId);
  if (!conflict) {
    return;
  }
  const duration = interval.endsAt.getTime() - interval.startsAt.getTime();
  throw bookingConflict(
    conflict.id,
    await suggestOpenings(roomId, interval.startsAt, duration),
  );
}

export async function createBooking(input: CreateBookingInput): Promise<Booking> {
  const interval = parseInterval(input.startsAt, input.endsAt);
  await requireRoomAndUser(input.roomId, input.userId);
  await requireFree(input.roomId, interval);

  return repository.create({
    roomId: input.roomId,
    userId: input.userId,
    title: input.title,
    ...interval,
  });
}

export async function getBooking(id: string): Promise<Booking> {
  const booking = await repository.findById(id);
  if (!booking) {
    throw notFound('Booking');
  }
  return booking;
}

export async function listBookings(query: ListBookingsInput): Promise<Page<Booking>> {
  const limit = normalizeLimit(query.limit);
  const offset = normalizeOffset(query.offset);
  const [data, total] = await repository.list({
    roomId: query.roomId,
    userId: query.userId,
    status: query.status,
    from: query.from ? parseInstant(query.from) : undefined,
    to: query.to ? parseInstant(query.to) : undefined,
    limit,
    offset,
  });
  return paginated(data, total, limit, offset);
}

export async function updateBooking(id: string, input: UpdateBookingInput): Promise<Booking> {
  const current = await getBooking(id);
  const roomId = input.roomId ?? current.roomId;
  const userId = input.userId ?? current.userId;
  const interval = requireOrdered({
    startsAt: input.startsAt !== undefined ? parseInstant(input.startsAt) : current.startsAt,
    endsAt: input.endsAt !== undefined ? parseInstant(input.endsAt) : current.endsAt,
  });

  if (input.roomId !== undefined || input.userId !== undefined) {
    await requireRoomAndUser(roomId, userId);
  }
  // A cancelled booking does not hold the room, so moving it cannot clash.
  if (current.status === BOOKING_ACTIVE) {
    await requireFree(roomId, interval, id);
  }

  return repository.update(id, {
    ...(input.roomId !== undefined ? { roomId } : {}),
    ...(input.userId !== undefined ? { userId } : {}),
    ...(input.title !== undefined ? { title: input.title } : {}),
    ...(input.startsAt !== undefined ? { startsAt: interval.startsAt } : {}),
    ...(input.endsAt !== undefined ? { endsAt: interval.endsAt } : {}),
  });
}

export async function cancelBooking(id: string): Promise<Booking> {
  const booking = await getBooking(id);
  if (booking.status === BOOKING_CANCELLED) {
    return booking;
  }
  return repository.updateStatus(id, BOOKING_CANCELLED);
}

export async function deleteBooking(id: string): Promise<void> {
  await getBooking(id);
  await repository.remove(id);
}
EOF
