import { buildApp } from '/app/src/app.js';
import { prisma } from '/app/src/db/client.js';

const app = await buildApp({ logger: false });
await app.ready();
await prisma.booking.deleteMany(); await prisma.room.deleteMany(); await prisma.user.deleteMany();

const room = await app.inject({ method: 'POST', url: '/rooms', payload: { name: 'Probe', capacity: 4 } });
const user = await app.inject({ method: 'POST', url: '/users', payload: { name: 'P', email: 'p@example.com' } });
const roomId = room.json().id, userId = user.json().id;
const H = 3_600_000;
const at = (h: number) => new Date(Date.UTC(2030, 0, 1) + h * H).toISOString();
const book = (s: number, e: number, title = 'T') =>
  app.inject({ method: 'POST', url: '/bookings', payload: { roomId, userId, title, startsAt: at(s), endsAt: at(e) } });

console.log('base 10-11 =>', (await book(10, 11, 'base')).statusCode);
const a = await book(9, 10.5, 'A');
console.log('A) straddles existing start =>', a.statusCode, JSON.stringify(a.json().error?.details));
console.log('B) fully contains existing  =>', (await book(9, 12, 'B')).statusCode);
console.log('C) reversed 20 -> 19        =>', (await book(20, 19, 'C')).statusCode, (await book(20,19,'C')).json().error?.message);
console.log('D) zero-length 30 -> 30     =>', (await book(30, 30, 'D')).statusCode);
console.log('E) unknown room             =>', (await app.inject({ method: 'POST', url: '/bookings', payload: { roomId: 'nope', userId, title: 'E', startsAt: at(40), endsAt: at(41) } })).statusCode);
const moved = await book(50, 51, 'toMove');
const f = await app.inject({ method: 'PATCH', url: `/bookings/${moved.json().id}`, payload: { startsAt: at(10), endsAt: at(11) } });
console.log('F) PATCH onto occupied      =>', f.statusCode);
console.log('G) adjacent 11-12           =>', (await book(11, 12, 'adj')).statusCode);

const av = await app.inject({ method: 'GET', url: `/availability?roomId=${roomId}&from=${at(8)}&to=${at(16)}&durationMinutes=30` });
console.log('\nH) availability 08:00-16:00:', JSON.stringify(av.json(), null, 1));

const rows = await prisma.booking.findMany({ orderBy: { startsAt: 'asc' } });
console.log('\nrows:', rows.map(b => `${b.title} ${b.startsAt.toISOString().slice(11,16)}->${b.endsAt.toISOString().slice(11,16)}`));
await app.close(); await prisma.$disconnect();
EOF
