  it('rejects a booking that starts before and runs into an active booking', async () => {
    await book(24, 25);
    const response = await book(23.5, 24.5, 'Straddles the start');
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('rejects a booking that swallows an active booking whole', async () => {
    await book(24, 25);
    const response = await book(23, 26, 'Swallows');
    expect(response.statusCode).toBe(409);
  });

  it('accepts a booking that ends exactly when another starts', async () => {
    await book(24, 25);
    const response = await book(23, 24, 'Adjacent before');
    expect(response.statusCode).toBe(201);
  });

  it('ignores bookings in another room when detecting a conflict', async () => {
    await book(24, 25);
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId: other.json().id,
        userId,
        title: 'Same time elsewhere',
        startsAt: inHours(24),
        endsAt: inHours(25),
      },
    });
    expect(response.statusCode).toBe(201);
  });

  it('offers free slots alongside a conflict', async () => {
    await book(24, 25);
    const response = await book(24.5, 25.5, 'Overlap');
    const [first] = response.json().error.details.suggestions;
    expect(first.startsAt).toBe(inHours(25));
    expect(new Date(first.endsAt).getTime() - new Date(first.startsAt).getTime()).toBe(HOUR);
  });

  it('suggests a slot that can be booked as it is', async () => {
    await book(24, 25);
    const conflict = await book(24.5, 25.5, 'Overlap');
    const [suggestion] = conflict.json().error.details.suggestions;
    const retry = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId, title: 'Retry', ...suggestion },
    });
    expect(retry.statusCode).toBe(201);
  });

  it('suggests one opening per gap in a fragmented calendar', async () => {
    await book(24, 25);
    await book(26, 27);
    await book(28, 29);
    const response = await book(24, 25, 'Needs an hour');
    expect(response.json().error.details.suggestions).toEqual([
      { startsAt: inHours(25), endsAt: inHours(26) },
      { startsAt: inHours(27), endsAt: inHours(28) },
      { startsAt: inHours(29), endsAt: inHours(30) },
    ]);
  });

  it('skips a gap that is too short for the requested duration', async () => {
    await book(24, 25);
    await book(25.5, 27);
    const response = await book(24, 26, 'Needs two hours');
    const [first] = response.json().error.details.suggestions;
    expect(first.startsAt).toBe(inHours(27));
  });

  it('rejects a booking that ends before it starts', async () => {
    const response = await book(25, 24, 'Backwards');
    expect(response.statusCode).toBe(400);
    expect(response.json().error.code).toBe('VALIDATION_ERROR');
  });

  it('rejects a booking with no duration', async () => {
    const response = await book(24, 24, 'Instant');
    expect(response.statusCode).toBe(400);
  });

  it('answers 404 when the room does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId: 'missing', userId, title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.message).toBe('Room not found');
  });

  it('answers 404 when the user does not exist', async () => {
    const response = await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: { roomId, userId: 'missing', title: 'Sync', startsAt: inHours(24), endsAt: inHours(25) },
    });
    expect(response.statusCode).toBe(404);
    expect(response.json().error.message).toBe('User not found');
  });

  it('refuses to move a booking on top of another one', async () => {
    await book(24, 25);
    const second = await book(30, 31, 'Later');
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${second.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(409);
    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
  });

  it('lets a booking keep its own slot while being edited', async () => {
    const created = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${created.json().id}`,
      payload: { startsAt: inHours(24.5), endsAt: inHours(25.5) },
    });
    expect(response.statusCode).toBe(200);
    expect(response.json().startsAt).toBe(inHours(24.5));
  });

  it('refuses to move a booking into an occupied slot in another room', async () => {
    const other = await app.inject({
      method: 'POST',
      url: '/rooms',
      payload: { name: 'Borealis', capacity: 4 },
    });
    await app.inject({
      method: 'POST',
      url: '/bookings',
      payload: {
        roomId: other.json().id,
        userId,
        title: 'Taken',
        startsAt: inHours(24),
        endsAt: inHours(25),
      },
    });
    const mine = await book(24, 25);
    const response = await app.inject({
      method: 'PATCH',
      url: `/bookings/${mine.json().id}`,
      payload: { roomId: other.json().id },
    });
    expect(response.statusCode).toBe(409);
  });

  it('rejects an edit that turns the interval backwards', async () => {
